CREATE VIEW eve.eve_can_remove_from_assortment (`product` String, `channel` String, `can_remove` UInt8) AS SELECT sc.product AS product, sc.channel AS channel, (coalesce(pub.cnt, 0) = 0) AND (coalesce(eoh.cnt, 0) = 0) AS can_remove FROM (SELECT DISTINCT product, location AS channel FROM eve.eve_ma_stylecolorchannelattributes WHERE (record_state = 0) AND ((product, updated_at) IN (SELECT product, max(updated_at) FROM eve.eve_ma_stylecolorchannelattributes GROUP BY product))) AS sc LEFT JOIN (SELECT product, count() AS cnt FROM eve.eve_p_dc_adj WHERE (((product, time, updated_at) IN (SELECT product, time, max(updated_at) FROM eve.eve_p_dc_adj GROUP BY product, time)) AND (dc_publish > 0)) OR (dc_onorder > 0) GROUP BY product) AS pub ON pub.product = sc.product LEFT JOIN (SELECT product, channel, count() AS cnt FROM eve.eve_eohdata_stylecolor WHERE eohu > 0 GROUP BY product, channel) AS eoh ON (eoh.product = sc.product) AND (eoh.channel = sc.channel)
