CREATE VIEW eve.eve_p_mfp_class_dept_month_view_hier (`product` String, `location` String, `time` String, `ttl_storecount` Float64, `net_sls_u` Float64, `net_sls_r` Float64, `net_sls_c` Float64, `boh_r` Float64, `boh_u` Float64, `boh_c` Float64, `eoh_u` Float64, `eoh_r` Float64, `eoh_c` Float64, `rec_u` Float64, `rec_c` Float64, `rec_r` Float64, `on_order_u` Float64, `on_order_c` Float64, `on_order_r` Float64, `pos_md_r` Float64, `perm_md_r` Float64, `invadj_u` Float64, `invadj_r` Float64, `invadj_c` Float64, `donations_u` Float64, `donations_r` Float64, `donations_c` Float64, `eventdate` Date, `category` String, `class` String, `department` Nullable(String), `division` Nullable(String), `month` String, `quarter` Nullable(String), `season` Nullable(String), `year` Nullable(String)) AS SELECT product, location, time, ttl_storecount, net_sls_u, net_sls_r, net_sls_c, boh_r, boh_u, boh_c, eoh_u, eoh_r, eoh_c, rec_u, rec_c, rec_r, on_order_u, on_order_c, on_order_r, pos_md_r, perm_md_r, invadj_u, invadj_r, invadj_c, donations_u, donations_r, donations_c, eventdate, class AS category, class, department, division, id AS month, ancestor0 AS quarter, ancestor1 AS season, ancestor2 AS year FROM (SELECT product, location, time, ttl_storecount, net_sls_u, net_sls_r, net_sls_c, boh_r, boh_u, boh_c, eoh_u, eoh_r, eoh_c, rec_u, rec_c, rec_r, on_order_u, on_order_c, on_order_r, pos_md_r, perm_md_r, invadj_u, invadj_r, invadj_c, donations_u, donations_r, donations_c, eventdate, class AS category, class, department, division, time AS id FROM (SELECT *, product AS class FROM eve.eve_p_mfp) AS a ANY LEFT JOIN (SELECT class, department, division, count(*) AS cnt FROM eve.eve_stylecolor_hier_attr WHERE (class IN (SELECT DISTINCT product FROM eve.eve_p_mfp)) AND ((product, updated_at) IN (SELECT product, max(updated_at) FROM eve.eve_stylecolor_hier_attr GROUP BY product)) GROUP BY class, department, division ORDER BY count(*) DESC LIMIT 1 BY class) USING (class)) AS x ANY LEFT JOIN eve.eve_h_timestd_tbl USING (id)
